    <div id="content-rin" class="tab-content"><div class="info-grid"><div class="info-item"><div class="label">📍 地點</div><div class="value" id="rin-location"></div></div><div class="info-item"><div class="label">👚 打扮</div><div class="value" id="rin-outfit"></div></div><div class="info-item"><div class="label">💜 心聲</div><div class="value" id="rin-thoughts"></div></div><div class="info-item"><div class="label">🎯 當前目標</div><div class="value" id="rin-current-goal"></div></div><div class="info-item" style="grid-column: span 2;"><div class="label">📝 今日任務</div><div class="value" id="rin-today-mission"></div></div></div></div>
</div>
<script>
    function SafeGetValue(obj, path, defaultValue = "N/A") {
        if(typeof path !== 'string') return defaultValue;
        let keys = path.split('.');
        let current = obj;
        for (let i = 0; i < keys.length; i++) {
            if (current === undefined || current === null || typeof current !== 'object' || !current.hasOwnProperty(keys[i])) {
                return defaultValue;
            }
            current = current[keys[i]];
        }
        return (current === undefined || current === null) ? defaultValue : current;
    }

    function renderTasks(elementId, tasks) {
        const container = document.getElementById(elementId);
        if (!container) return;
        if (!Array.isArray(tasks) || tasks.length === 0) {
            container.innerHTML = '<span>無</span>';
            return;
        }
        let html = '<ul>';
        tasks.forEach(task => {
            if(typeof task === 'object' && task !== null && task.hasOwnProperty('任務')){
                 html += `<li>🎯 ${task.任務} ➔ 🎁 ${task.獎勵 || '無'}</li>`;
            }
        });
        html += '</ul>';
        container.innerHTML = html;
    }

    async function initDisplay() {
        try {
            const messages = await getChatMessages(getCurrentMessageId());
            if (!messages || messages.length === 0 || !messages[0].data) {
                document.getElementById('status-bar-container').innerHTML = "<div style='color:red;padding:10px;'>無法加載狀態數據</div>";
                return;
            }
            const characterData = messages[0].data.stat_data;
            if (!characterData) {
                 document.getElementById('status-bar-container').innerHTML = "<div style='color:red;padding:10px;'>無法加載狀態數據</div>";
                return;
            }

            const worldDateEl = document.getElementById('world-date');
            if (worldDateEl) {
                const year = SafeGetValue(characterData, '世界.年分');
                const month = SafeGetValue(characterData, '世界.月份');
                const day = SafeGetValue(characterData, '世界.日期');
                const weekday = SafeGetValue(characterData, '世界.星期');
                worldDateEl.innerText = `${year}年${month}月${day}日 (${weekday})`;
            }
            document.getElementById('world-time').innerText = SafeGetValue(characterData, '世界.時間');

            document.getElementById('momo-location').innerText = SafeGetValue(characterData, '桃.地點');
            document.getElementById('momo-outfit').innerText = SafeGetValue(characterData, '桃.當前打扮');
            document.getElementById('momo-thoughts').innerText = SafeGetValue(characterData, '桃.心聲');
            document.getElementById('momo-current-goal').innerText = SafeGetValue(characterData, '桃.當前目標');
            renderTasks('momo-today-mission', SafeGetValue(characterData, '桃.今日任務', []));

            document.getElementById('rin-location').innerText = SafeGetValue(characterData, '凛.地點');
            document.getElementById('rin-outfit').innerText = SafeGetValue(characterData, '凛.當前打扮');
            document.getElementById('rin-thoughts').innerText = SafeGetValue(characterData, '凛.心聲');
            document.getElementById('rin-current-goal').innerText = SafeGetValue(characterData, '凛.當前目標');
            renderTasks('rin-today-mission', SafeGetValue(characterData, '凛.今日任務', []));

        } catch (error) {
            document.getElementById('status-bar-container').innerHTML = `<div style='color:red;padding:10px;'>狀態欄加載出錯: ${error.message}</div>`;
        }
    }

    function switchTab(tabName) {
        const tabContents = document.querySelectorAll('.tab-content');
        const tabButtons = document.querySelectorAll('.tab-btn');
        tabContents.forEach(content => content.classList.remove('active'));
        tabButtons.forEach(button => button.classList.remove('active'));
        document.getElementById('content-' + tabName).classList.add('active');
        document.getElementById('btn-' + tabName).classList.add('active');
    }

    document.addEventListener('DOMContentLoaded', () => {
        initDisplay();
        switchTab('world');
    });
</script>
</body>
</html>
